const isPosInt=n=>Number.isSafeInteger(n)&&n>0;
const checkNow=now=>{if(!Number.isSafeInteger(now)||now<0) throw new RangeError('now');};
const bad=m=>{throw new RangeError('snapshot: '+m);};
const isObj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const nonneg=n=>Number.isSafeInteger(n)&&n>=0;
const put=(o,k,v)=>Object.defineProperty(o,k,{value:v,writable:true,enumerable:true,configurable:true});
const ARITY={reserve:[3,5],fulfill:[2,3],refund:[2,2],expire:[1,1]};
function validate(d) {
  if(!isObj(d)) bad('not an object');
  if(d.version!==2) bad('version');
  for(const k of ['stock','prices','rows']) if(!isObj(d[k])) bad(k);
  for(const k of Object.keys(d.stock)) if(!nonneg(d.stock[k])) bad('stock');
  for(const k of Object.keys(d.prices)) if(typeof d.prices[k]!=='string'||!/^\d+$/.test(d.prices[k])) bad('prices');
  for(const k of Object.keys(d.rows)) {
    const r=d.rows[k];
    if(!isObj(r)||typeof r.sku!=='string'||typeof r.expired!=='boolean') bad('row');
    if(!isPosInt(r.qty)||!nonneg(r.deadline)||!nonneg(r.fulfilled)||!nonneg(r.refunded)) bad('row');
    if(r.refunded>r.fulfilled||r.fulfilled>r.qty) bad('row totals');
  }
  if('replay' in d) {
    if(!isObj(d.replay)) bad('replay');
    for(const k of Object.keys(d.replay)) {
      const e=d.replay[k];
      if(!isObj(e)||!Object.hasOwn(ARITY,e.op)||!Array.isArray(e.args)) bad('replay entry');
    }
  }
}
class Orders {
  constructor(stock,prices={}) { this.stock={...stock};this.prices={...prices};this.rows={};this.applied={}; }
  reserve(id,sku,qty,now=0,ttl=10) {
    if(!isPosInt(qty)) throw new RangeError('qty');
    if(!isPosInt(ttl)) throw new RangeError('ttl');
    checkNow(now);
    if(!Number.isSafeInteger(now+ttl)) throw new RangeError('ttl');
    this.expire(now);
    if(Object.hasOwn(this.rows,id)) {const r=this.rows[id];return !r.expired&&r.sku===sku&&r.qty===qty;}
    if((this.stock[sku]||0)<qty) return false;
    this.stock[sku]-=qty;this.rows[id]={sku,qty,deadline:now+ttl,expired:false,fulfilled:0,refunded:0};return true;
  }
  expire(now) {
    checkNow(now);
    let n=0;
    for(const r of Object.values(this.rows)) {
      if(!r.expired&&now>=r.deadline) {r.expired=true;this.stock[r.sku]=(this.stock[r.sku]||0)+r.qty-r.fulfilled;n++;}
    }
    return n;
  }
  dumps() {
    const prices={};
    for(const k of Object.keys(this.prices)) put(prices,k,typeof this.prices[k]==='bigint'||typeof this.prices[k]==='number'?String(this.prices[k]):this.prices[k]);
    const d={version:2,stock:this.stock,prices,rows:this.rows};
    if(Object.keys(this.applied).length) d.replay=this.applied;
    validate(d);
    return JSON.stringify(d);
  }
  static loads(text) {
    let d;
    if(typeof text!=='string') bad('text');
    try {d=JSON.parse(text);} catch(e) {bad('malformed JSON');}
    validate(d);
    const o=new Orders(d.stock,d.prices);
    for(const k of Object.keys(d.rows)) put(o.rows,k,{...d.rows[k]});
    if('replay' in d) for(const k of Object.keys(d.replay)) put(o.applied,k,{op:d.replay[k].op,args:JSON.parse(JSON.stringify(d.replay[k].args))});
    return o;
  }
  replay(events) {
    if(!Array.isArray(events)) throw new RangeError('events');
    const [lo,hi]=[0,1];
    for(const ev of events) {
      if(!isObj(ev)||typeof ev.event!=='string'||!Object.hasOwn(ARITY,ev.op)||!Array.isArray(ev.args)) throw new RangeError('event');
      const a=ev.args,n=ARITY[ev.op];
      if(a.length<n[lo]||a.length>n[hi]) throw new RangeError('args');
      let j;
      try {j=JSON.stringify(a);} catch(e) {throw new RangeError('args');}
      if(JSON.parse(j).length!==a.length||JSON.stringify(JSON.parse(j))!==j) throw new RangeError('args');
    }
    const saved=JSON.parse(JSON.stringify({stock:this.stock,rows:this.rows,applied:this.applied}));
    const restore=()=>{
      for(const k of ['stock','rows','applied']) {
        const o={};for(const x of Object.keys(saved[k])) put(o,x,saved[k][x]);
        this[k]=o;
      }
    };
    let count=0;
    try {
      for(const ev of events) {
        const rec={op:ev.op,args:JSON.parse(JSON.stringify(ev.args))};
        if(Object.hasOwn(this.applied,ev.event)) {
          const p=this.applied[ev.event];
          if(p.op===rec.op&&JSON.stringify(p.args)===JSON.stringify(rec.args)) continue;
          throw new RangeError('conflicting event');
        }
        const a=rec.args;
        if(ev.op!=='expire'&&typeof a[0]!=='string') throw new RangeError('id');
        if(ev.op==='reserve'&&typeof a[1]!=='string') throw new RangeError('sku');
        if(ev.op==='reserve'&&this.reserve(...a)!==true) throw new RangeError('rejected');
        if((ev.op==='fulfill'||ev.op==='refund')&&this[ev.op](...a)===null) throw new RangeError('rejected');
        if(ev.op==='expire') this.expire(...a);
        put(this.applied,ev.event,rec);count++;
      }
    } catch(e) {
      restore();
      throw e instanceof RangeError?e:new RangeError('replay: '+e.message);
    }
    return count;
  }
  cents(sku,qty) {
    const p=this.prices[sku];
    if(p===undefined) return 0n;
    const t=String(p);
    return /^\d+$/.test(t)?BigInt(t)*BigInt(qty):null;
  }
  fulfill(id,qty,now=0) {
    if(!isPosInt(qty)) throw new RangeError('qty');
    checkNow(now);
    this.expire(now);
    const r=Object.hasOwn(this.rows,id)?this.rows[id]:null;
    if(!r||r.expired||qty>r.qty-r.fulfilled) return null;
    const c=this.cents(r.sku,qty);
    if(c===null) return null;
    r.fulfilled+=qty;
    return c;
  }
  refund(id,qty) {
    if(!isPosInt(qty)) throw new RangeError('qty');
    const r=Object.hasOwn(this.rows,id)?this.rows[id]:null;
    if(!r||qty>r.fulfilled-r.refunded) return null;
    const c=this.cents(r.sku,qty);
    if(c===null) return null;
    r.refunded+=qty;
    this.stock[r.sku]=(this.stock[r.sku]||0)+qty;
    return c;
  }
  available(sku,now) {
    if(now!==undefined) this.expire(now);
    return this.stock[sku]||0;
  }
}
module.exports={Orders};
